function auditRequirements(lines) {
  const issues = [];
  for (const line of lines) {
    const t = line.trim();
    if (!t || t.startsWith('#')) continue;
    if (!t.includes('==')) issues.push('unpinned: ' + t);
  }
  return { total: lines.filter((l) => l.trim() && !l.trim().startsWith('#')).length, issues };
}
const reqs = ['pandas==2.2.3', 'scikit-learn>=1.0', 'numpy', '# data stack', 'python-dotenv==1.0.1'];
const r = auditRequirements(reqs);
console.log('deps=' + r.total);
console.log('unpinned=' + r.issues.length);
for (const i of r.issues) console.log(i);

